package local.ondemand;
import org.json.*;import java.util.*;import java.util.regex.*;
final class SourcePolicy {
 static class Options {String language="fallback",order="match";boolean experimental;boolean skipStalled=true;float maxGb;}
 static class Source {JSONObject raw;String url,label,codec="",fingerprint;int quality,bits,copies=1;long bytes;boolean hdr,dv,englishReported,subsReported;MediaHeader.Info header;long checkedAt,checkBytes,checkMs,failedUntil;String checkState="Not checked";boolean connected;String externalSub="";String experienceKey="",experienceNote="";long avoidUntil;boolean verified,verifiedEnglish;
  boolean playable(){return Api.playable(raw);}
  boolean englishAudio(){if(header!=null&&header.audioKnown())return header.englishAudio();return verifiedEnglish||englishReported||(header!=null&&header.englishAudio());}
  boolean englishSubs(){return header!=null&&header.englishSubs()||!externalSub.isEmpty();}
  String language(){if(verifiedEnglish)return "English audio · observed in playback";if(header!=null&&header.englishAudio())return "English audio · confirmed";if(englishAudio())return "English audio · reported";if(englishSubs())return "Original audio + English subtitles";if(subsReported)return "English subtitles need checking";return "Audio / subtitle language unknown";}
  boolean smooth(){return (quality==1080||quality==720||header!=null&&header.width>0&&header.width<=1920&&header.height<=1088)&&codec.equals("H.264")&&bits<=8&&!hdr&&!dv;}
  String reason(){if(avoidUntil>System.currentTimeMillis())return "Previously stalled · "+experienceNote+" · available to retry";if(verified)return "Smooth playback observed here";if(!playable())return "Not cached HTTPS playback · no automatic downloads";if(failedUntil>System.currentTimeMillis())return "Connection failed recently · retry available";if(smooth())return header!=null?"Pi-friendly format · header inspected":"Pi-friendly format · release labels only";if(quality>=2160&&codec.equals("H.264"))return "4K H.264 exceeds Pi hardware target";if(quality>=2160)return "4K tests struggled · experimental on this Pi";if(dv||hdr)return "HDR / Dolby Vision playback path unverified";if(bits>8)return "Higher bit depth · outside Pi Smooth";if(codec.equals("HEVC"))return "1080p HEVC is untested here";return "Missing or untested format details";}
  void apply(MediaHeader.Info h){header=h;if(!h.codec.isEmpty())codec=h.codec;if(h.width>0){quality=h.width>1920||h.height>1088?2160:h.width>1280||h.height>720?1080:h.width>=1200||h.height>=700?720:h.height;}if(h.bits>0)bits=h.bits;hdr|=h.hdr;dv|=h.dv;}
 }
 static String digest(String s){try{byte[] b=java.security.MessageDigest.getInstance("SHA-256").digest(s.getBytes("UTF-8"));StringBuilder out=new StringBuilder();for(byte v:b)out.append(String.format(Locale.ROOT,"%02x",v&255));return out.toString();}catch(Exception e){throw new IllegalStateException();}}
 static boolean has(String s,String expression){return Pattern.compile(expression,Pattern.CASE_INSENSITIVE).matcher(s).find();}
 static Source parse(JSONObject raw){Source s=new Source();s.raw=raw;s.url=raw.optString("url");JSONObject hints=raw.optJSONObject("behaviorHints");String filename=hints==null?"":hints.optString("filename");s.label=raw.optString("name")+"\n"+raw.optString("description",raw.optString("title"))+"\n"+filename;String t=s.label.toLowerCase(Locale.ROOT);
  s.quality=has(t,"(?:2160p|\\b4k\\b)")?2160:has(t,"1080[pi]")?1080:has(t,"720p")?720:0;s.codec=has(t,"(?:h[ ._-]?264|x264|\\bavc\\b)")?"H.264":has(t,"(?:h[ ._-]?265|x265|\\bhevc\\b)")?"HEVC":has(t,"\\bav1\\b")?"AV1":has(t,"\\bvp9\\b")?"VP9":"";s.bits=has(t,"(?:10[ ._-]?bit|hi10p|high10)")?10:has(t,"12[ ._-]?bit")?12:has(t,"8[ ._-]?bit")?8:0;s.dv=has(t,"(?:dolby[ ._-]?vision|\\bdv\\b|\\bdovi\\b)");s.hdr=s.dv||has(t,"(?:hdr|hlg)");
  for(String line:s.label.split("\n")){if(has(line,"(?:subtitles?|\\bsubs?\\b|forced)"))continue;if(line.contains("🇬🇧")||line.contains("🇺🇸")||has(line,"(?:^|[._\\-\\[\\]() +])ENG(?:$|[._\\-\\[\\]() +])|audio[^\n]{0,12}english"))s.englishReported=true;}
  JSONArray audio=raw.optJSONArray("audioLanguages");if(audio!=null)for(int j=0;j<audio.length();j++)s.englishReported|=MediaHeader.english(audio.optString(j));JSONArray subs=raw.optJSONArray("subtitles");if(subs!=null)for(int j=0;j<subs.length();j++){JSONObject sub=subs.optJSONObject(j);if(sub!=null&&MediaHeader.english(sub.optString("lang"))&&!has(sub.optString("id"),"forced"))s.subsReported=true;}
  s.bytes=hints==null?0:hints.optLong("videoSize",0);if(s.bytes<=0){Matcher m=Pattern.compile("([0-9]+(?:\\.[0-9]+)?)\\s*(gib|gb|mib|mb)",Pattern.CASE_INSENSITIVE).matcher(s.label);if(m.find())s.bytes=(long)(Double.parseDouble(m.group(1))*(m.group(2).toLowerCase(Locale.ROOT).startsWith("g")?1e9:1e6));}
  String hash=raw.optString("infoHash");String identity=!hash.isEmpty()&&raw.has("fileIdx")?hash+":"+raw.optInt("fileIdx"):hints!=null&&!hints.optString("videoHash").isEmpty()?hints.optString("videoHash")+":"+filename+":"+s.bytes:s.url.isEmpty()?s.label+":"+s.bytes:s.url;s.fingerprint=digest(identity);return s;
 }
 static List<Source> parse(JSONArray a){LinkedHashMap<String,Source> out=new LinkedHashMap<>();if(a!=null)for(int i=0;i<a.length();i++){JSONObject j=a.optJSONObject(i);if(j==null)continue;Source s=parse(j);Source prior=out.get(s.fingerprint);if(prior!=null)prior.copies++;else out.put(s.fingerprint,s);}return new ArrayList<>(out.values());}
 static List<Source> recommended(List<Source> all,Options o){List<Source> candidates=new ArrayList<>();for(Source s:all)if(s.playable()&&(!o.skipStalled||s.avoidUntil<=System.currentTimeMillis())&&s.failedUntil<=System.currentTimeMillis()&&(s.smooth()||o.experimental)&&!(o.maxGb>0&&s.bytes>o.maxGb*1e9))candidates.add(s);List<Source> english=new ArrayList<>(),subs=new ArrayList<>();for(Source s:candidates){if(s.englishAudio())english.add(s);else if(s.englishSubs())subs.add(s);}if(o.language.equals("audio"))candidates=english;else if(!o.language.equals("any"))candidates=english.isEmpty()?subs:english;
  candidates.sort((a,b)->{int c=Boolean.compare(!a.smooth(),!b.smooth());if(c!=0)return c;if(!o.order.equals("demand")){c=Integer.compare(b.quality,a.quality);if(c!=0)return c;}c=Boolean.compare(!a.verified,!b.verified);if(c!=0)return c;c=Boolean.compare(a.header==null,b.header==null);if(c!=0)return c;if(o.order.equals("demand")){if(a.bytes>0&&b.bytes>0){c=Long.compare(a.bytes,b.bytes);if(c!=0)return c;}}else{c=Integer.compare(b.quality,a.quality);if(c!=0)return c;}if(a.bytes>0&&b.bytes>0){c=Long.compare(a.bytes,b.bytes);if(c!=0)return c;}return 0;});return candidates;
 }
 static String evidence(Source s){return s.avoidUntil>System.currentTimeMillis()?"Previously stalled":s.verified?"✓ Tested smooth on this Pi":s.header!=null?"Header checked · playback untested":"Playback untested";}
 static String size(Source s){return s.bytes>0?String.format(Locale.ROOT,"%.1f GB",s.bytes/1e9):"Size unknown";}
 static String summary(Source s){return (s.quality>0?(s.quality>=2160?"4K":s.quality+"p"):"Resolution unknown")+" · "+(s.codec.isEmpty()?"Codec unknown":s.codec)+(s.dv?" · Dolby Vision":s.hdr?" · HDR":" · No HDR flagged");}
}
